import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { listJobs } from "../services/api";

export default function HMDashboard() {
  const navigate = useNavigate();
  const [jobs, setJobs] = useState([]);
  useEffect(() => { listJobs().then(r => setJobs(r.data)).catch(() => {}); }, []);

  return (
    <div style={{ animation: "fadeUp 0.5s ease" }}>
      <div style={{ marginBottom: 40 }}>
        <div className="badge badge-teal" style={{ marginBottom: 16 }}>Hiring Manager</div>
        <h1 style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 800, fontSize: 36, color: "var(--text-primary)", marginBottom: 8 }}>
          Active Positions
        </h1>
        <p style={{ color: "var(--text-secondary)", fontSize: 16 }}>Review shortlists and approve candidates for outreach.</p>
      </div>

      {jobs.length === 0 ? (
        <div className="card" style={{ padding: 60, textAlign: "center" }}>
          <div style={{ fontSize: 40, marginBottom: 12 }}>📋</div>
          <div style={{ fontFamily: "Plus Jakarta Sans", fontSize: 18, color: "var(--text-primary)", marginBottom: 8 }}>No positions yet</div>
          <div style={{ color: "var(--text-secondary)", fontSize: 14 }}>A recruiter needs to create a job first.</div>
        </div>
      ) : (
        <div style={{ display: "grid", gap: 16, gridTemplateColumns: "repeat(auto-fill, minmax(320px, 1fr))" }}>
          {jobs.map((j, i) => (
            <div key={j.id} className="card" style={{ padding: 28, animation: `fadeUp 0.4s ease ${i * 0.08}s both` }}>
              <div style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 700, fontSize: 18, color: "var(--text-primary)", marginBottom: 8 }}>
                {j.title}
              </div>
              <div style={{ fontSize: 13, color: "var(--text-secondary)", marginBottom: 6 }}>
                {j.industry && <span>{j.industry} · </span>}
                {j.min_experience > 0 && <span>{j.min_experience}+ years exp</span>}
              </div>
              <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 20 }}>
                Skills: {j.required_skills?.slice(0, 60)}...
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button className="btn-primary" style={{ flex: 1, padding: "10px 16px", fontSize: 13 }}
                  onClick={() => navigate(`/hm-review/${j.id}`)}>
                  Review Shortlist
                </button>
                <button className="btn-secondary" style={{ padding: "10px 16px", fontSize: 13 }}
                  onClick={() => navigate(`/results/${j.id}`)}>
                  View All
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
